// FindByActive is the resolver for the findByActive field.
func (r *queryResolver) FindByActive(ctx context.Context, input *model.FindAllTransactionRequest) (*model.APIResponsePaginationTransactionDeleteAt, error) {
	return ResolverHandle(r.ResolverHandle, "FindByActive", ctx, func(ctx context.Context) (*model.APIResponsePaginationTransactionDeleteAt, error) {
		page := int32(1)
		pageSize := int32(10)
		search := ""
		if input != nil {
			if input.Page != nil {
				page = int32(*input.Page)
			}
			if input.PageSize != nil {
				pageSize = int32(*input.PageSize)
			}
			if input.Search != nil {
				search = *input.Search
			}
		}
		if page <= 0 {
			page = 1
		}
		if pageSize <= 0 {
			pageSize = 10
		}

		if data, found := r.TransactionGraphql.Cache.GetCachedTransactionActiveCache(ctx, input); found {
			return data, nil
		}

		req := &pb.FindAllTransactionRequest{
			Page:     page,
			PageSize: pageSize,
			Search:   search,
		}

		transactions, err := r.TransactionGraphql.TransactionQueryClient.FindByActive(ctx, req)
		if err != nil {
			return nil, r.handleGraphQLError(err, "FindByActive")
		}

		active := r.TransactionGraphql.Mapping.ToGraphqlResponsePaginationTransaction(transactions)

		var data []*model.TransactionResponseDeleteAt
		for _, tx := range active.Data {
			data = append(data, &model.TransactionResponseDeleteAt{
				ID:            tx.ID,
				OrderID:       tx.OrderID,
				MerchantID:    tx.MerchantID,
				PaymentMethod: tx.PaymentMethod,
				Amount:        tx.Amount,
				PaymentStatus: tx.PaymentStatus,
				CreatedAt:     tx.CreatedAt,
				UpdatedAt:     tx.UpdatedAt,
			})
		}

		res := &model.APIResponsePaginationTransactionDeleteAt{
			Status:     active.Status,
			Message:    active.Message,
			Data:       data,
			Pagination: active.Pagination,
		}

		r.TransactionGraphql.Cache.SetCachedTransactionActiveCache(ctx, input, res)

		return res, nil
	})
}

